import{_ as s,l as i,o as a,c,v as t,p as d,x as o,d as l,i as n,S as p}from"./chunks/framework.InCnrqk-.js";const _=JSON.parse('{"title":"RISC-V 虚拟化 H 扩展","description":"","frontmatter":{"title":"RISC-V 虚拟化 H 扩展","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/riscv-h-extension.md","filePath":"cs/riscv-h-extension.md","lastUpdated":1789023840000}'),h={name:"cs/riscv-h-extension.md"};function S(A,e,E,V,g,P){const r=i("Mermaid");return a(),c("div",null,[e[1]||(e[1]=t('<h1 id="risc-v-虚拟化-h-扩展" tabindex="-1">RISC-V 虚拟化 H 扩展 <a class="header-anchor" href="#risc-v-虚拟化-h-扩展" aria-label="Permalink to &quot;RISC-V 虚拟化 H 扩展&quot;">​</a></h1><div class="epigraph"><p>H 扩展给 S 态加上 hypervisor：客机仍走自己的 Sv39，客物理地址再经 G-stage 译到宿主物理地址，影子页表不必跟每一次客内核填 PTE。</p><footer>—— 据 The RISC-V Instruction Set Manual, Volume II: Privileged Architecture；ARM ARM（EL2 / Stage-2）；Intel SDM（EPT）整理</footer></div><p><a href="/cs/sv39-page-table">上一课</a>钉的是单层 <code>satp</code>。<a href="/cs/ept-npt">EPT 与 NPT</a> 已在 x86 侧讲过两层翻译。<a href="/cs/arm-vs-riscv">ARM 对 RISC-V</a> 把虚拟化对照留在 EL2。缺口是 <strong>RISC-V H</strong>：VS/VU 模式与 <code>hgatp</code>，而不是再画一遍三级 VPN。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>没有 H 时，VMM 只能用影子页表，或把客内核当用户进程跑。<a href="/cs/sv39-page-table">Sv39</a> 的 <code>satp</code> 只有一套根。H 扩展引入：HS（hypervisor 扩展的 S）、VS（虚拟 S）、VU（虚拟 U）。客 OS 以为自己在写 <code>satp</code>，硬件实际用 VS-stage 把 GVA→GPA，再用 <code>hgatp</code> 的 G-stage 把 GPA→HPA。缺口不是再解释「什么是虚拟机」，而是<strong>第二层页表挂在哪颗 CSR 上</strong>。</p><p>两层都可以缺：VS 缺页交给客内核；G-stage 缺页（GPA 未映射）交给 hypervisor，对应 EPT violation。</p><h3 id="h-不是「再开一个-m-态」" tabindex="-1">H 不是「再开一个 M 态」 <a class="header-anchor" href="#h-不是「再开一个-m-态」" aria-label="Permalink to &quot;H 不是「再开一个 M 态」&quot;">​</a></h3><p>M 态仍是最高。Hypervisor 跑在 HS，不靠把全部敏感指令降到机器态模拟。把 H 理解成第三份 RV32I，对照课会失去两阶段 MMU。也不把本课写成某开源 hypervisor 的启动日志。</p><p><span class="marginnote">RISC-V Privileged Spec 的 Hypervisor 章是权威。ARM Stage-2 与 Intel EPT 是对照，不在本课重写项格式。本课不背 <code>hstatus</code> 每一位。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>VMM 为每个客机配置 <code>hgatp</code>（G-stage 根，格式可与 Sv39 同类树）。客内核照常填自己的页表。取指与 load/store 经两层；TLB 缓存组合结果，<code>HFENCE.VVMA</code> / <code>HFENCE.GVMA</code> 分别冲客与 G-stage，对象不是 <a href="/cs/fence-instructions">内存 fence</a>。</p><p>Hypervisor 需要读客虚拟地址：<code>HLV</code>/<code>HSV</code> 一类指令在 HS 按 VS 翻译访问客内存，避免自己切 <code>satp</code>。中断：注入与委托走 <code>hideleg</code>/<code>hvip</code>，对照 GIC 虚拟化，本课只点名。</p>',12)),(a(),d(p,null,{default:o(()=>[n(r,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20GVA%5B%22%E5%AE%A2%E8%99%9A%E5%9C%B0%E5%9D%80%20GVA%22%5D%20--%3E%20VS%5B%22VS-stage%20satp%22%5D%0A%20%20VS%20--%3E%20GPA%5B%22%E5%AE%A2%E7%89%A9%E7%90%86%20GPA%22%5D%0A%20%20GPA%20--%3E%20GS%5B%22G-stage%20hgatp%22%5D%0A%20%20GS%20--%3E%20HPA%5B%22%E5%AE%BF%E4%B8%BB%E7%89%A9%E7%90%86%20HPA%22%5D%0A%20%20HPA%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E7%94%A8%E6%88%B7%E6%80%81%20ALU%20%E6%89%A9%E5%B1%95%E4%BB%8D%E7%BC%BA%22%5D%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[l(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<p>嵌套虚拟化与 IOMMU 第二层不在本课展开；<a href="/cs/dma-scatter-gather">DMA</a> 的设备地址仍要 IOMMU，不是 <code>hgatp</code> 自动覆盖。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>ISA 对照轴上，H 把 RISC-V 的特权故事补到与 EL2/VMX 可引用的位置：页表格式仍是 Sv39 一类树，只是串了两次。用户态整数、压缩、向量并不因 H 改变编码。下一课位操作扩展回到 ALU：地址生成与位域仍是编译器每天发射的缺口，与虚拟化正交。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不保证某硅片已实现 H，不写 virtio 队列，不把侧信道写成利用步骤。不把 Type-1/Type-2 产品分类当 ISA 定义。</p><p>后课默认：H 扩展用 VS-stage + G-stage 两层翻译；<code>hgatp</code> 是宿主看客物理的根。下一课位操作。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>VS 翻译客虚地址，G-stage 再译客物理。</li><li>对照 EPT / ARM Stage-2，CSR 与栅栏名不同。</li><li>不替代 M 态，也不改用户 ALU。</li><li>出处：RISC-V Privileged Spec（H）；ARM ARM；Intel SDM（EPT）。</li></ul>',8))])}const H=s(h,[["render",S]]);export{_ as __pageData,H as default};
